{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "The tryptophan analogue 5-[18F]FEHTrp showed low brain uptake (0.84 %ID/g) in mice, indicating that an indole/tryptophan-containing scaffold can have poor CNS access; the query shares this tryptophan/indole core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Sarpogrelate, a methoxyaryl tertiary-amine-containing drug, reached only 0.25–2% of plasma concentration in rat brain, demonstrating that similar methoxybenzyl/basic-amine features do not ensure meaningful BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "[18F]MPPF, a methoxyphenyl-piperazine amide, is a P-gp substrate with very low brain uptake (0.05% ID/g) in rats; the query contains analogous methoxyaryl, amide, and basic piperidine/piperazine-like motifs and is likely subject to efflux.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "BMS-378806, an indole-containing amide, had a brain-to-plasma AUC ratio of only 0.06 in rats, providing direct evidence that indole-amide compounds with similar polarity and size can be effectively excluded from the CNS.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show poor BBB penetration, very low brain/plasma ratios, or efflux-mediated exclusion. The query shares multiple CNS-penetration liabilities—tryptophan/indole, methoxybenzyl, amide, and basic piperidine—so it is predicted to lack meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or unbound brain concentration measurement exists for the exact query molecule.",
    "No explicit P-gp/BCRP transporter assay is available for the query itself.",
    "Evidence is derived from close analogues rather than the query, although assay-transfer scores are high."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

